from semver_range import satisfies, max_satisfying
checks = [('1.9.9','<=1.x',True),('2.0.0-0','<=1.x',False),('2.0.0','>1.x',True),('1.9.9','>1.x',False),('1.2.9','1.2.x',True),('1.3.0-0','1.2.x',False),('1.3.0-0','<=1.2',False),('1.2.0','<1.2',False),('1.2.0-0','>=1.2',False)]
for v,r,e in checks: assert satisfies(v,r) is e,(v,r,e)
assert max_satisfying(['1.2.3+one','1.2.3+two'], '1.2.3') == '1.2.3+one'
for bad in ['1.2.x.3','1.x.2','1.2.3-01','01.2.3']:
 try: satisfies('1.2.3', bad)
 except ValueError: pass
 else: raise AssertionError(bad)
print('additional boundary checks passed')
